import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
} from 'typeorm';

import { UserStatus } from '../../../shared/enums/user-status.enum';

/**
 * Physical database table mapping representing a registered platform user account.
 * Extends the basic account details with multitenant and verification states.
 */
@Entity('users')
export class User {
  /**
   * Unique UUID identifier generated by the database.
   */
  @PrimaryGeneratedColumn('uuid')
  id: string;

  /**
   * Unique user email address used for credentials authentication.
   */
  @Column({ unique: true })
  email: string;

  /**
   * Salted and hashed password string (Bcrypt hash with cost >= 12).
   */
  @Column({ name: 'password_hash' })
  passwordHash: string;

  /**
   * User display full name. Unique across the platform.
   */
  @Column({ name: 'full_name', length: 100 })
  fullName: string;

  /**
   * Toggled to true if individual provider mode is enabled.
   */
  @Column({ name: 'provider_mode', default: false })
  providerMode: boolean;

  /**
   * Toggled to true if user account has administrator privileges.
   */
  @Column({ name: 'is_admin', default: false })
  isAdmin: boolean;

  /**
   * The status state of the user account.
   */
  @Column({
    type: 'varchar',
    enum: UserStatus,
    default: UserStatus.PENDING_VERIFICATION,
  })
  status: UserStatus;

  /**
   * Timestamp record indicating when the user last logged in or out.
   */
  @Column({
    name: 'last_login_at',
    type: 'timestamp with time zone',
    nullable: true,
  })
  lastLoginAt: Date | null;

  /**
   * Timestamp record indicating when the user profile was originally registered.
   */
  @CreateDateColumn({ name: 'created_at' })
  createdAt: Date;

  /**
   * Timestamp record indicating when the user profile details were last modified.
   */
  @UpdateDateColumn({ name: 'updated_at' })
  updatedAt: Date;
}
